<div class="toolbar"><?php foreach($varsayilan as $k=>$v):?><a class="btn <?= $k===$secili?'btn-primary':'' ?>" href="?sayfa=<?= $k ?>"><?= e($v[0]) ?></a><?php endforeach;?></div><form method="post" class="form" id="kurumsalForm"><?= csrf_field() ?><input type="hidden" name="anahtar" value="<?= e($secili) ?>"><label>Sayfa Başlığı<input name="baslik" value="<?= e($icerik['baslik']) ?>"></label><label>İçerik</label><div class="html-editor"><div class="html-editor-tools"><button type="button" data-cmd="bold"><b>Kalın</b></button><button type="button" data-cmd="italic"><i>İtalik</i></button><button type="button" data-cmd="formatBlock" data-value="h2">Başlık</button><button type="button" data-cmd="insertUnorderedList">• Liste</button><button type="button" data-cmd="createLink">Bağlantı</button><button type="button" data-cmd="removeFormat">Biçimi temizle</button></div><div id="htmlEditor" class="html-editor-area" contenteditable="true"><?= guvenli_html($icerik['icerik']) ?></div></div><textarea name="icerik" id="htmlSource" hidden></textarea><p class="muted">Görünüm alanında düzenleyin; Kaydet düğmesi HTML içeriğini sayfaya aktarır.</p><div class="form-actions"><button class="btn btn-primary">Kaydet</button><a class="btn" target="_blank" href="<?= BASE_URL ?>/<?= $secili ?>.php">Sayfayı görüntüle</a></div></form><script>const e=document.getElementById('htmlEditor'),s=document.getElementById('htmlSource');document.querySelectorAll('[data-cmd]').forEach(b=>b.addEventListener('click',()=>{let v=b.dataset.value||null;if(b.dataset.cmd==='createLink'){v=prompt('Bağlantı adresi:','https://');if(!v)return;}document.execCommand(b.dataset.cmd,false,v);e.focus();}));document.getElementById('kurumsalForm').addEventListener('submit',()=>s.value=e.innerHTML);</script>
